static void printNum(int n) {
    if (n == 0) {
        return;
    }
    System.out.print(n + " ");
    printNum(n - 1);
    System.out.print(n + " ");
}

public class Fib {
    static int calls = 0;

    static int fib(int n) {
        calls++;
        if (n == 0 || n == 1) {
            return 1;
        }
        return fib(n - 1) + fib(n - 2);
    }

    public static void main(String[] args) {
        int r = fib(5);
        System.out.println(r + " " + calls);
    }
}
